const char *dwr3_boundary_filter_name(const DWR3_BOUNDARY_FILTER_MATERIAL_T material) {
	switch (material) {
		case DWR3_BOUNDARY_FILTER_MATERIAL_ABSORBER: return "Absorber";
		case DWR3_BOUNDARY_FILTER_MATERIAL_PLASTER: return "Plaster";
		case DWR3_BOUNDARY_FILTER_MATERIAL_WOOD: return "Wood";
		case DWR3_BOUNDARY_FILTER_MATERIAL_CONCRETE: return "Concrete";
		default: break;
	}
	return NULL;
}
